// Developer reference module (route #/_template). Shows every core API in a small physics example:
// a 2D rotation generated by J (plot2d + handle) and a 3D rotation about a draggable axis (scene3d).
// Copy this structure when writing a new module.

import * as ui from '../core/ui.js';
import { plot2d } from '../core/plot2d.js';
import { scene3d } from '../core/three-kit.js';
import { mat, vec, expSO3, TAU } from '../core/la.js';
import { texMatrix, texNum, fmt, fmtDeg } from '../core/format.js';

export default function mount(root, ctx) {
  // ---- state (ctx.state persists across remounts, e.g. theme toggles)
  const S = ctx.state;
  S.theta ??= 0.9;
  S.v ??= [1.2, 0.4];
  S.axis ??= [0.3, 0.4, 0.87];

  // ---- layout
  const pg = ctx.page({
    lede: 'Developer template: a generator $\\alg{J}$ and the finite rotation $\\grp{R(\\theta)=e^{\\theta J}}$ it produces, in 2D and 3D.',
    columns: 2,
  });
  const v2 = pg.view({ title: 'Plane: $\\grp{R(\\theta)}\\,v$', hint: 'drag the handle · scroll to zoom' });
  const v3 = pg.view({ title: 'Space: rotation about $\\hat n$', hint: 'drag the axis tip · drag empty space to orbit' });

  // ---- 2D view
  const J = [
    [0, -1],
    [1, 0],
  ];
  const p = plot2d(v2.body, ctx.scope, {
    x: [-2, 2],
    y: [-2, 2],
    axisLabels: ['x', 'y'],
    draw(p) {
      p.vectorField((x, y) => mat.mulv(J, [x, y]), { color: 'alg', step: 34 }); // the generator as a flow
      p.circle([0, 0], vec.norm(S.v), { color: 'grp', width: 1.5, dash: [5, 5], alpha: 0.7 }); // orbit
      const Rv = vec.rot2(S.v, S.theta);
      p.arrow([0, 0], S.v, { color: 'muted', width: 2 });
      p.arrow([0, 0], Rv, { color: 'grp', width: 3 });
      p.tex('\\grp{R(\\theta)v}', Rv, { offset: [16, -12] });
    },
  });
  p.handle({
    get: () => S.v,
    set: (q) => {
      S.v = q;
      update();
    },
    color: 'ink2',
    label: 'v',
  });

  // ---- 3D view
  const k = scene3d(v3.body, ctx.scope, { camera: [3.2, 2.4, 2.0] });
  k.axes({ length: 1.3 });
  k.wireSphere({ radius: 1, opacity: 0.18 });
  const axisArrow = k.arrow([0, 0, 0], S.axis, { color: 'alg', radius: 0.025 });
  const tip = k.sphere({ radius: 0.07, color: 'alg', position: S.axis });
  const body = k.arrow([0, 0, 0], [1, 0, 0], { color: 'grp', radius: 0.03 });
  const trail = k.line([], { color: 'grp', width: 2, opacity: 0.8 });
  k.label('\\hat n', [0, 0, 0], { color: 'alg' });
  k.draggable(tip, {
    constrain: k.onSphere([0, 0, 0], 1),
    onDrag: (q) => {
      S.axis = vec.normalize(q);
      update();
    },
  });

  // ---- panel
  const sec = pg.section('Rotation');
  const sTheta = ui.slider(sec, {
    label: 'Angle $\\theta$',
    min: 0,
    max: TAU,
    step: 0.01,
    value: S.theta,
    format: (x) => fmtDeg(x),
    onInput: (x) => {
      S.theta = x;
      update();
    },
  });
  const play = ui.playButton(sec, { playing: false });
  ui.buttons(sec, [{ label: 'Reset', onClick: () => sTheta.set(0) }]);
  const secR = pg.section('Readout');
  const out = ui.readout(secR, { label: 'Generator and group element' });
  const kv = ui.keyValue(secR, [['$|v|$ (conserved)', '']]);
  ui.legend(secR, [
    { color: 'alg', label: 'generator $J$' },
    { color: 'grp', label: 'rotated vector' },
  ]);
  ui.experiments(pg.section('Try this'), [
    { title: 'Quarter turn', text: 'Set $\\theta=\\pi/2$: $e^{\\theta J}=J$.', apply: () => sTheta.set(Math.PI / 2) },
    { title: 'Full turn', text: '$\\theta=2\\pi$ returns every vector to itself.', apply: () => sTheta.set(TAU) },
  ]);

  // ---- animation
  ctx.scope.frame((dt) => {
    if (!play.playing) return;
    sTheta.set((S.theta + dt * 0.8) % TAU);
  });

  // ---- notes
  pg.note(`<h2>What you see</h2><p>The faint arrows are the vector field $\\alg{J}x$ — the generator as an infinitesimal motion.
    Following it for time $\\theta$ gives the finite rotation $\\grp{R(\\theta)}=e^{\\theta J}$:</p>
    $$e^{\\theta J}=\\sum_n \\frac{(\\theta J)^n}{n!}=\\cos\\theta\\,\\id+\\sin\\theta\\,J,\\qquad J^2=-\\id .$$`);
  pg.note(`<h2>Physics</h2><p>Rotations preserve length: $|v|$ is conserved along the flow. In quantum mechanics the same
    generator appears as $L_z=-i\\,\\partial_\\varphi$ and $R(\\theta)=e^{-i\\theta L_z}$.</p>`);

  function update() {
    const Rv = vec.rot2(S.v, S.theta);
    p.invalidate();
    out.set(`J=${texMatrix(J, 0)},\\quad R(\\theta)=${texMatrix(mat.expm(mat.scale(J, S.theta)), 3)}`);
    kv.set('$|v|$ (conserved)', fmt(vec.norm(Rv), 3));
    axisArrow.set([0, 0, 0], S.axis);
    tip.position.set(...S.axis);
    const R = expSO3(vec.scale(S.axis, S.theta));
    body.set([0, 0, 0], mat.mulv(R, [1, 0, 0]));
    const pts = [];
    for (let i = 0; i <= 64; i++) pts.push(mat.mulv(expSO3(vec.scale(S.axis, (S.theta * i) / 64)), [1, 0, 0]));
    trail.setPoints(pts);
  }
  update();
  void texNum;
}
